const packs: Record<LocaleKey, CopyPack> = {
  en: { title: 'Debt to Income Ratio Calculator', description: 'Compare your current debt-to-income ratio with a new loan scenario, convert amounts across eleven major currencies, and test the threshold you choose before adding another monthly payment.', intro: 'A new monthly payment can look manageable on its own while changing the share of income already committed to debt. Enter the income basis and payments you know, then test the new commitment against a threshold you choose.', formula: 'The basic calculation is monthly debt payments ÷ selected monthly income × 100. The current scenario uses existing payments; the projected scenario adds the proposed payment.', limit: 'A threshold is useful for comparing options, but it is not a universal approval rule. Lenders can define income, debt and limits differently.', faq: [{ question: 'What is a debt-to-income ratio?', answer: 'It is the share of selected monthly income that goes toward monthly debt payments. The calculator expresses that share as a percentage.' }, { question: 'Should I use gross or net income?', answer: 'Use the basis that matches your comparison and keep it consistent. Lenders and products may define income and debt differently.' }, { question: 'Does this predict approval?', answer: 'No. It compares the values you enter and cannot decide whether a lender will approve an application.' }], howTo: [{ name: 'Choose the basis', text: 'Choose a currency, then select gross or net income.' }, { name: 'Add current payments', text: 'Enter the monthly debt payments you already make.' }, { name: 'Model the new loan', text: 'Add the proposed payment, term and threshold.' }, { name: 'Read the change', text: 'Compare both ratios, remaining income and the margin to your threshold.' }], seoTitle: 'Compare the current and projected debt load', seoResultTitle: 'What the comparison shows', seoResult: 'The current ratio uses existing monthly payments. The projected ratio adds the proposed payment, while the term shows the scheduled total of that new payment.', seoTipTitle: 'Treat the threshold as a scenario, not a verdict', seoTip: 'Use the threshold to compare options, not as a promise of approval. Check the lender’s definitions and your complete household budget before committing.', seoList: ['Whether the new payment moves the ratio above your chosen limit.', 'How much income remains after current and projected payments.', 'How many percentage points the new payment adds.', 'The scheduled total across the entered term.'], seoClosing: 'Currency switching is a display conversion using dated reference rates, not a live quote.' },
  de: { title: 'Schulden-Einkommens-Quotenrechner', description: 'Vergleiche deine aktuelle Schuldenquote mit einem neuen Kredit, rechne Beträge zwischen EUR, USD, GBP und RUB um und prüfe deinen eigenen Grenzwert.', intro: 'Eine neue Monatsrate kann allein tragbar wirken und trotzdem den bereits gebundenen Einkommensanteil verändern. Trage deine Werte ein und vergleiche das neue Szenario mit deinem Grenzwert.', formula: 'Die Grundrechnung lautet monatliche Schuldzahlungen ÷ gewähltes Monatseinkommen × 100. Das geplante Szenario ergänzt die neue Rate.', limit: 'Der Grenzwert dient dem Vergleich, ist aber keine allgemeine Zusage für eine Kreditentscheidung. Anbieter können Einkommen und Schulden anders definieren.', faq: [{ question: 'Was bedeutet die Schulden-Einkommens-Quote?', answer: 'Sie zeigt, welcher Anteil des gewählten Monatseinkommens für monatliche Schuldzahlungen verwendet wird.' }, { question: 'Soll ich Brutto- oder Nettoeinkommen verwenden?', answer: 'Nutze die Grundlage, die zu deinem Vergleich passt, und bleibe in beiden Szenarien dabei.' }, { question: 'Sagt der Rechner eine Zusage voraus?', answer: 'Nein. Er vergleicht nur deine Eingaben und ersetzt keine Prüfung durch einen Kreditgeber.' }], howTo: [{ name: 'Grundlage wählen', text: 'Wähle die Währung sowie Brutto- oder Nettoeinkommen.' }, { name: 'Aktuelle Raten eintragen', text: 'Trage deine bestehenden monatlichen Zahlungen ein.' }, { name: 'Neuen Kredit prüfen', text: 'Gib Rate, Laufzeit und Grenzwert ein.' }, { name: 'Ergebnis lesen', text: 'Vergleiche Quoten, verbleibendes Einkommen und Abstand zum Grenzwert.' }], seoTitle: 'Aktuelle und geplante Schuldenlast vergleichen', seoResultTitle: 'Was der Vergleich zeigt', seoResult: 'Die aktuelle Quote nutzt bestehende Zahlungen. Die geplante Quote ergänzt die neue Rate; die Laufzeit zeigt deren geplante Gesamtsumme.', seoTipTitle: 'Den Grenzwert als Szenario verstehen', seoTip: 'Ein Grenzwert ist eine Vergleichshilfe und keine Zusage. Prüfe die Definitionen des Anbieters und dein gesamtes Haushaltsbudget.', seoList: ['Ob die neue Rate deinen gewählten Grenzwert überschreitet.', 'Wie viel Einkommen nach den Zahlungen bleibt.', 'Wie viele Prozentpunkte die neue Rate hinzufügt.', 'Welche Gesamtsumme über die Laufzeit entsteht.'], seoClosing: 'Der Währungswechsel ist eine Anzeigeumrechnung mit datierten Referenzkursen, kein Live-Kurs.' },
  es: { title: 'Calculadora de ratio deuda-ingresos', description: 'Compara tu ratio de deuda actual con un nuevo préstamo, convierte importes entre EUR, USD, GBP y RUB y prueba el umbral que elijas.', intro: 'Una cuota nueva puede parecer asumible por separado y cambiar mucho la parte de ingresos ya comprometida. Introduce tus pagos y comprueba el nuevo escenario con tu propio umbral.', formula: 'El cálculo es pagos mensuales de deuda ÷ ingresos mensuales elegidos × 100. El escenario proyectado suma la nueva cuota.', limit: 'El umbral sirve para comparar opciones, pero no es una regla universal de aprobación. Cada entidad puede definir ingresos y deuda de forma distinta.', faq: [{ question: '¿Qué es el ratio deuda-ingresos?', answer: 'Es la parte de los ingresos mensuales elegidos que se destina a pagar deudas mensuales, expresada como porcentaje.' }, { question: '¿Uso ingresos brutos o netos?', answer: 'Usa la base que encaje con tu comparación y mantenla igual en los dos escenarios.' }, { question: '¿Predice si me aprobarán el préstamo?', answer: 'No. Solo compara los datos que introduces y no sustituye el análisis de una entidad.' }], howTo: [{ name: 'Elige la base', text: 'Selecciona moneda e ingresos brutos o netos.' }, { name: 'Añade tus pagos', text: 'Introduce las cuotas mensuales que ya pagas.' }, { name: 'Modela el préstamo', text: 'Añade la cuota propuesta, el plazo y tu umbral.' }, { name: 'Lee el cambio', text: 'Compara ambos ratios, los ingresos restantes y el margen.' }], seoTitle: 'Compara tu deuda actual y proyectada', seoResultTitle: 'Qué te enseña la comparación', seoResult: 'El ratio actual usa tus pagos existentes. El proyectado suma la nueva cuota y el plazo muestra el total programado de esa cuota.', seoTipTitle: 'Usa el umbral como escenario, no como veredicto', seoTip: 'El umbral te ayuda a comparar opciones, pero no garantiza una aprobación. Contrasta las definiciones de la entidad con tu presupuesto completo.', seoList: ['Si la nueva cuota supera el límite elegido.', 'Cuánto ingreso queda después de los pagos.', 'Cuántos puntos porcentuales añade la nueva cuota.', 'El total programado durante el plazo.'], seoClosing: 'Cambiar de moneda es una conversión de visualización con tipos de referencia fechados, no una cotización en tiempo real.' },
  fr: { title: 'Calculateur du ratio dette-revenu', description: 'Comparez votre ratio actuel avec un nouveau prêt, convertissez les montants entre EUR, USD, GBP et RUB et testez le seuil de votre choix.', intro: 'Une nouvelle mensualité peut sembler supportable seule tout en augmentant la part du revenu déjà consacrée aux dettes. Saisissez vos montants et comparez le scénario.', formula: 'Le calcul est mensualités de dettes ÷ revenu mensuel choisi × 100. Le scénario projeté ajoute la nouvelle mensualité.', limit: 'Le seuil sert à comparer des options, mais ne constitue pas une règle universelle d’acceptation. Les prêteurs peuvent définir les revenus et les dettes autrement.', faq: [{ question: 'Qu’est-ce que le ratio dette-revenu ?', answer: 'C’est la part du revenu mensuel choisi consacrée aux paiements de dettes, exprimée en pourcentage.' }, { question: 'Dois-je utiliser le revenu brut ou net ?', answer: 'Choisissez la base adaptée à votre comparaison et conservez-la dans les deux scénarios.' }, { question: 'Le calculateur prédit-il une acceptation ?', answer: 'Non. Il compare vos données et ne remplace pas l’étude du prêteur.' }], howTo: [{ name: 'Choisir la base', text: 'Choisissez la devise et le revenu brut ou net.' }, { name: 'Ajouter les paiements', text: 'Saisissez les mensualités que vous payez déjà.' }, { name: 'Tester le nouveau prêt', text: 'Ajoutez la mensualité, la durée et votre seuil.' }, { name: 'Lire l’évolution', text: 'Comparez les ratios, le revenu restant et la marge.' }], seoTitle: 'Comparer la dette actuelle et projetée', seoResultTitle: 'Ce que montre la comparaison', seoResult: 'Le ratio actuel utilise les paiements existants. Le ratio projeté ajoute la nouvelle mensualité et la durée affiche son total prévu.', seoTipTitle: 'Considérez le seuil comme un scénario', seoTip: 'Un seuil aide à comparer, mais ne garantit pas une acceptation. Vérifiez les définitions du prêteur et votre budget complet.', seoList: ['Le dépassement éventuel de votre limite.', 'Le revenu restant après les paiements.', 'Les points ajoutés par la nouvelle mensualité.', 'Le total prévu sur la durée saisie.'], seoClosing: 'Le changement de devise est une conversion d’affichage avec des taux de référence datés, pas un cours en direct.' },
  id: { title: 'Kalkulator Rasio Utang terhadap Pendapatan', description: 'Bandingkan rasio utang saat ini dengan pinjaman baru, konversi jumlah EUR, USD, GBP, dan RUB, lalu uji batas pilihan Anda.', intro: 'Cicilan baru dapat terlihat ringan sendiri tetapi mengubah bagian pendapatan yang sudah terikat. Masukkan pembayaran Anda dan bandingkan skenario baru dengan batas yang dipilih.', formula: 'Perhitungannya adalah pembayaran utang bulanan ÷ pendapatan bulanan yang dipilih × 100. Skenario proyeksi menambahkan cicilan baru.', limit: 'Batas membantu membandingkan pilihan, tetapi bukan aturan persetujuan universal. Pemberi pinjaman dapat mendefinisikan pendapatan dan utang secara berbeda.', faq: [{ question: 'Apa itu rasio utang terhadap pendapatan?', answer: 'Rasio ini menunjukkan bagian pendapatan bulanan yang digunakan untuk membayar utang bulanan, dalam bentuk persentase.' }, { question: 'Haruskah memakai pendapatan kotor atau bersih?', answer: 'Gunakan dasar yang sesuai dengan perbandingan Anda dan pertahankan untuk kedua skenario.' }, { question: 'Apakah kalkulator ini memprediksi persetujuan?', answer: 'Tidak. Kalkulator hanya membandingkan data Anda dan bukan keputusan pemberi pinjaman.' }], howTo: [{ name: 'Pilih dasar', text: 'Pilih mata uang dan pendapatan kotor atau bersih.' }, { name: 'Masukkan pembayaran', text: 'Tambahkan pembayaran utang bulanan yang sudah berjalan.' }, { name: 'Uji pinjaman baru', text: 'Masukkan cicilan, jangka waktu, dan batas Anda.' }, { name: 'Baca perubahannya', text: 'Bandingkan rasio, pendapatan tersisa, dan jarak ke batas.' }], seoTitle: 'Bandingkan beban utang saat ini dan proyeksi', seoResultTitle: 'Apa yang ditunjukkan perbandingan', seoResult: 'Rasio saat ini memakai pembayaran yang ada. Rasio proyeksi menambahkan cicilan baru, sedangkan jangka waktu menunjukkan total terjadwalnya.', seoTipTitle: 'Gunakan batas sebagai skenario, bukan keputusan', seoTip: 'Batas berguna untuk membandingkan pilihan, tetapi tidak menjamin persetujuan. Periksa definisi pemberi pinjaman dan anggaran rumah tangga Anda.', seoList: ['Apakah cicilan baru melewati batas yang dipilih.', 'Berapa pendapatan yang tersisa setelah pembayaran.', 'Berapa poin persentase yang ditambahkan.', 'Total terjadwal selama jangka waktu.'], seoClosing: 'Pergantian mata uang adalah konversi tampilan dengan kurs referensi bertanggal, bukan kurs langsung.' },
  it: { title: 'Calcolatore del rapporto debito-reddito', description: 'Confronta il rapporto attuale con un nuovo prestito, converti gli importi tra EUR, USD, GBP e RUB e prova la soglia che scegli.', intro: 'Una nuova rata può sembrare gestibile da sola e cambiare la quota di reddito già impegnata. Inserisci i pagamenti e confronta lo scenario previsto.', formula: 'Il calcolo è pagamenti mensili del debito ÷ reddito mensile scelto × 100. Lo scenario previsto aggiunge la nuova rata.', limit: 'La soglia serve a confrontare le opzioni, ma non è una regola universale di approvazione. Gli istituti possono definire reddito e debito in modo diverso.', faq: [{ question: 'Cos’è il rapporto debito-reddito?', answer: 'È la parte del reddito mensile scelto destinata ai pagamenti dei debiti, espressa in percentuale.' }, { question: 'Uso il reddito lordo o netto?', answer: 'Scegli la base adatta al confronto e usala in entrambi gli scenari.' }, { question: 'Il calcolatore prevede l’approvazione?', answer: 'No. Confronta i dati inseriti e non sostituisce la valutazione del finanziatore.' }], howTo: [{ name: 'Scegli la base', text: 'Scegli valuta e reddito lordo o netto.' }, { name: 'Inserisci i pagamenti', text: 'Aggiungi le rate mensili già presenti.' }, { name: 'Prova il nuovo prestito', text: 'Inserisci rata, durata e soglia.' }, { name: 'Leggi la variazione', text: 'Confronta rapporti, reddito residuo e margine.' }], seoTitle: 'Confronta il debito attuale e previsto', seoResultTitle: 'Cosa mostra il confronto', seoResult: 'Il rapporto attuale usa i pagamenti esistenti. Quello previsto aggiunge la nuova rata e la durata mostra il totale programmato.', seoTipTitle: 'Considera la soglia uno scenario', seoTip: 'La soglia aiuta a confrontare, ma non garantisce l’approvazione. Verifica definizioni e budget completo.', seoList: ['Se la nuova rata supera il limite scelto.', 'Quanto reddito rimane dopo i pagamenti.', 'Quanti punti percentuali aggiunge la rata.', 'Il totale previsto per tutta la durata.'], seoClosing: 'Cambiare valuta è una conversione di visualizzazione con tassi di riferimento datati, non una quotazione in tempo reale.' },
  ja: { title: '借入負担率計算ツール', description: '現在の借入負担率と新しいローンのシナリオを比較し、EUR・USD・GBP・RUBを換算して、設定した上限を確認します。', intro: '新しい返済額は単独では無理がなく見えても、すでに返済に回している収入の割合を変えます。金額を入力して予測シナリオを比べましょう。', formula: '計算式は毎月の債務返済額 ÷ 選択した月収 × 100です。予測シナリオでは新しい返済額を加えます。', limit: '上限は選択肢を比べるための目安であり、審査結果を示す普遍的なルールではありません。', faq: [{ question: '借入負担率とは何ですか？', answer: '選択した月収のうち、毎月の借入返済に使われる割合をパーセントで示したものです。' }, { question: '総収入と手取りのどちらを使いますか？', answer: '目的に合う基準を選び、現在と予測の両方で同じ基準を使ってください。' }, { question: '審査の可否を予測できますか？', answer: 'いいえ。入力値を比較するツールであり、金融機関の審査を代替しません。' }], howTo: [{ name: '基準を選ぶ', text: '通貨と総収入または手取りを選択します。' }, { name: '現在の返済を入力', text: 'すでに支払っている毎月の返済額を入力します。' }, { name: '新しいローンを試す', text: '新しい返済額、期間、上限を入力します。' }, { name: '変化を読む', text: '比率、残る収入、上限までの余裕を比べます。' }], seoTitle: '現在と予測の借入負担を比較', seoResultTitle: '比較で分かること', seoResult: '現在の比率は既存の返済額を使います。予測比率は新しい返済額を加え、期間から予定総額を確認できます。', seoTipTitle: '上限は判定ではなくシナリオ', seoTip: '上限は選択肢の比較に使い、承認の保証とは考えないでください。金融機関の定義と家計全体を確認しましょう。', seoList: ['新しい返済額で上限を超えるか。', '返済後に残る毎月の収入。', '新しい返済額が加えるポイント数。', '入力した期間の予定総額。'], seoClosing: '通貨変更は日付付きの参考レートによる表示換算で、リアルタイム相場ではありません。' },
  ko: { title: '부채 소득 비율 계산기', description: '현재 부채 소득 비율과 신규 대출 시나리오를 비교하고 EUR, USD, GBP, RUB 금액을 변환해 원하는 기준선을 확인하세요.', intro: '새 월 상환액은 단독으로는 감당할 만해 보여도 이미 부채에 쓰는 소득의 비율을 바꿀 수 있습니다. 금액을 입력하고 예상 시나리오를 비교하세요.', formula: '계산식은 월 부채 상환액 ÷ 선택한 월 소득 × 100입니다. 예상 시나리오에는 신규 상환액이 더해집니다.', limit: '기준선은 선택지를 비교하기 위한 값이며 보편적인 승인 규칙이 아닙니다. 대출기관마다 소득과 부채의 정의가 다를 수 있습니다.', faq: [{ question: '부채 소득 비율이란 무엇인가요?', answer: '선택한 월 소득 중 매월 부채를 상환하는 데 쓰이는 비율을 백분율로 나타낸 값입니다.' }, { question: '총소득과 순소득 중 무엇을 사용하나요?', answer: '비교 목적에 맞는 기준을 선택하고 두 시나리오에서 동일하게 사용하세요.' }, { question: '대출 승인을 예측하나요?', answer: '아니요. 입력한 값을 비교할 뿐이며 대출기관의 심사를 대신하지 않습니다.' }], howTo: [{ name: '기준 선택', text: '통화와 총소득 또는 순소득을 선택합니다.' }, { name: '현재 상환액 입력', text: '이미 납부 중인 월 부채 상환액을 입력합니다.' }, { name: '신규 대출 모델링', text: '신규 상환액, 기간, 기준선을 입력합니다.' }, { name: '변화 확인', text: '비율과 남는 소득, 기준선까지의 여유를 비교합니다.' }], seoTitle: '현재와 예상 부채 부담 비교', seoResultTitle: '비교 결과로 알 수 있는 것', seoResult: '현재 비율은 기존 상환액을 사용합니다. 예상 비율은 신규 상환액을 더하고 기간으로 예정 총액을 보여줍니다.', seoTipTitle: '기준선은 판정이 아닌 시나리오', seoTip: '기준선은 비교용이며 승인 보장이 아닙니다. 대출기관의 정의와 전체 가계 예산을 확인하세요.', seoList: ['신규 상환액이 선택한 한도를 넘는지.', '상환 후 남는 소득이 얼마인지.', '신규 상환액이 더하는 퍼센트포인트.', '입력한 기간 동안의 예정 총액.'], seoClosing: '통화 변경은 날짜가 표시된 기준 환율을 이용한 화면 변환이며 실시간 시세가 아닙니다.' },
  nl: { title: 'Schuld-inkomensverhouding calculator', description: 'Vergelijk je huidige schuld-inkomensverhouding met een nieuwe lening, reken bedragen om tussen EUR, USD, GBP en RUB en test je eigen grens.', intro: 'Een nieuwe maandbetaling kan op zichzelf haalbaar lijken, maar het deel van je inkomen voor schulden veranderen. Vul je betalingen in en vergelijk het verwachte scenario.', formula: 'De berekening is maandelijkse schuld ÷ gekozen maandinkomen × 100. Het verwachte scenario telt de nieuwe betaling op.', limit: 'De grens helpt opties vergelijken, maar is geen universele goedkeuringsregel. Kredietverstrekkers kunnen inkomen en schuld anders definiëren.', faq: [{ question: 'Wat is de schuld-inkomensverhouding?', answer: 'Het is het aandeel van je gekozen maandinkomen dat naar maandelijkse schuldaflossingen gaat, uitgedrukt als percentage.' }, { question: 'Gebruik ik bruto- of netto-inkomen?', answer: 'Kies de basis die bij je vergelijking past en gebruik die in beide scenario’s.' }, { question: 'Voorspelt de calculator goedkeuring?', answer: 'Nee. Hij vergelijkt je invoer en vervangt geen beoordeling door een kredietverstrekker.' }], howTo: [{ name: 'Kies de basis', text: 'Kies valuta en bruto- of netto-inkomen.' }, { name: 'Voeg betalingen toe', text: 'Vul je bestaande maandelijkse schuldbetalingen in.' }, { name: 'Test de nieuwe lening', text: 'Voeg betaling, looptijd en grens toe.' }, { name: 'Lees de verandering', text: 'Vergelijk verhoudingen, resterend inkomen en marge.' }], seoTitle: 'Huidige en verwachte schuldenlast vergelijken', seoResultTitle: 'Wat de vergelijking laat zien', seoResult: 'De huidige verhouding gebruikt bestaande betalingen. De verwachte verhouding telt de nieuwe betaling op en de looptijd toont het geplande totaal.', seoTipTitle: 'Zie de grens als scenario', seoTip: 'Een grens helpt vergelijken, maar garandeert geen goedkeuring. Controleer de definities van de verstrekker en je volledige budget.', seoList: ['Of de nieuwe betaling je gekozen grens overschrijdt.', 'Hoeveel inkomen na de betalingen overblijft.', 'Hoeveel procentpunten de betaling toevoegt.', 'Het geplande totaal over de looptijd.'], seoClosing: 'Een valutawissel is een weergaveconversie met gedateerde referentiekoersen, geen live koers.' },
  pl: { title: 'Kalkulator relacji długu do dochodu', description: 'Porównaj obecną relację długu do dochodu z nową pożyczką, przelicz kwoty między EUR, USD, GBP i RUB oraz sprawdź własny próg.', intro: 'Nowa rata może wyglądać na łatwą do udźwignięcia, a jednocześnie zmienić część dochodu przeznaczoną już na długi. Wpisz płatności i porównaj scenariusz.', formula: 'Wzór to miesięczne spłaty długu ÷ wybrany miesięczny dochód × 100. Scenariusz przewidywany dodaje nową ratę.', limit: 'Próg służy do porównania opcji, ale nie jest uniwersalną zasadą decyzji kredytowej. Kredytodawcy mogą inaczej definiować dochód i dług.', faq: [{ question: 'Czym jest relacja długu do dochodu?', answer: 'Pokazuje, jaka część wybranego miesięcznego dochodu trafia na spłaty długów, jako procent.' }, { question: 'Użyć dochodu brutto czy netto?', answer: 'Wybierz podstawę odpowiednią do porównania i stosuj ją w obu scenariuszach.' }, { question: 'Czy kalkulator przewiduje zgodę kredytową?', answer: 'Nie. Porównuje podane wartości i nie zastępuje analizy kredytodawcy.' }], howTo: [{ name: 'Wybierz podstawę', text: 'Wybierz walutę oraz dochód brutto lub netto.' }, { name: 'Dodaj obecne raty', text: 'Wpisz miesięczne spłaty, które już ponosisz.' }, { name: 'Sprawdź nową pożyczkę', text: 'Dodaj ratę, okres i własny próg.' }, { name: 'Odczytaj zmianę', text: 'Porównaj wskaźniki, pozostały dochód i margines.' }], seoTitle: 'Porównaj obecne i przewidywane zadłużenie', seoResultTitle: 'Co pokazuje porównanie', seoResult: 'Obecny wskaźnik korzysta z istniejących rat. Przewidywany dodaje nową ratę, a okres pokazuje jej zaplanowaną sumę.', seoTipTitle: 'Traktuj próg jak scenariusz', seoTip: 'Próg pomaga porównywać opcje, ale nie gwarantuje zgody. Sprawdź definicje kredytodawcy i cały budżet.', seoList: ['Czy nowa rata przekracza wybrany limit.', 'Ile dochodu zostaje po płatnościach.', 'Ile punktów procentowych dodaje rata.', 'Łączna suma w podanym okresie.'], seoClosing: 'Zmiana waluty to przeliczenie prezentacyjne według datowanych kursów referencyjnych, nie kurs na żywo.' },
  pt: { title: 'Calculadora de rácio dívida-rendimento', description: 'Compare o rácio atual com um novo empréstimo, converta valores entre EUR, USD, GBP e RUB e teste o limite que escolher.', intro: 'Uma nova prestação pode parecer suportável isoladamente e alterar a parte do rendimento já comprometida. Introduza os pagamentos e compare o cenário previsto.', formula: 'O cálculo é pagamentos mensais de dívida ÷ rendimento mensal escolhido × 100. O cenário projetado soma a nova prestação.', limit: 'O limite ajuda a comparar opções, mas não é uma regra universal de aprovação. Os credores podem definir rendimento e dívida de formas diferentes.', faq: [{ question: 'O que é o rácio dívida-rendimento?', answer: 'É a parte do rendimento mensal escolhido destinada a pagamentos de dívida, expressa em percentagem.' }, { question: 'Uso rendimento bruto ou líquido?', answer: 'Escolha a base adequada à comparação e mantenha-a nos dois cenários.' }, { question: 'A calculadora prevê a aprovação?', answer: 'Não. Compara os valores introduzidos e não substitui a análise do credor.' }], howTo: [{ name: 'Escolher a base', text: 'Escolha a moeda e o rendimento bruto ou líquido.' }, { name: 'Adicionar pagamentos', text: 'Introduza as prestações mensais que já paga.' }, { name: 'Testar o novo empréstimo', text: 'Adicione prestação, prazo e limite.' }, { name: 'Ler a mudança', text: 'Compare rácios, rendimento restante e margem.' }], seoTitle: 'Compare a dívida atual e projetada', seoResultTitle: 'O que a comparação mostra', seoResult: 'O rácio atual usa os pagamentos existentes. O projetado soma a nova prestação e o prazo mostra o total previsto.', seoTipTitle: 'Veja o limite como cenário', seoTip: 'Um limite ajuda a comparar, mas não garante aprovação. Confirme as definições do credor e o orçamento completo.', seoList: ['Se a nova prestação ultrapassa o limite escolhido.', 'Quanto rendimento sobra depois dos pagamentos.', 'Quantos pontos percentuais a prestação acrescenta.', 'O total previsto ao longo do prazo.'], seoClosing: 'Mudar de moeda é uma conversão de apresentação com taxas de referência datadas, não uma cotação em direto.' },
  ru: { title: 'Калькулятор долговой нагрузки', description: 'Сравните текущую долговую нагрузку с новым кредитом, пересчитайте суммы между EUR, USD, GBP и RUB и проверьте выбранный порог.', intro: 'Новый ежемесячный платёж может казаться посильным сам по себе, но изменить долю дохода, уже занятую долгами. Введите данные и сравните прогнозный сценарий.', formula: 'Формула: ежемесячные платежи по долгам ÷ выбранный месячный доход × 100. В прогнозный сценарий добавляется новый платёж.', limit: 'Порог помогает сравнивать варианты, но не является универсальным правилом одобрения. Кредиторы могут по-разному определять доход и долг.', faq: [{ question: 'Что такое долговая нагрузка?', answer: 'Это доля выбранного месячного дохода, которая уходит на ежемесячные платежи по долгам, в процентах.' }, { question: 'Использовать доход до или после налогов?', answer: 'Выберите основу для своего сравнения и используйте её в обоих сценариях.' }, { question: 'Предсказывает ли калькулятор одобрение?', answer: 'Нет. Он сравнивает введённые значения и не заменяет проверку кредитора.' }], howTo: [{ name: 'Выберите основу', text: 'Выберите валюту и доход до или после налогов.' }, { name: 'Добавьте текущие платежи', text: 'Введите уже существующие ежемесячные платежи.' }, { name: 'Проверьте новый кредит', text: 'Укажите платёж, срок и свой порог.' }, { name: 'Оцените изменение', text: 'Сравните доли, оставшийся доход и запас до порога.' }], seoTitle: 'Сравните текущую и прогнозную долговую нагрузку', seoResultTitle: 'Что показывает сравнение', seoResult: 'Текущая доля использует существующие платежи. Прогнозная добавляет новый платёж, а срок показывает его плановую сумму.', seoTipTitle: 'Считайте порог сценарием, а не вердиктом', seoTip: 'Порог помогает сравнить варианты, но не гарантирует одобрение. Проверьте определения кредитора и весь семейный бюджет.', seoList: ['Превышает ли новый платёж выбранный предел.', 'Сколько дохода остаётся после платежей.', 'Сколько процентных пунктов добавляет платёж.', 'Плановую сумму за указанный срок.'], seoClosing: 'Смена валюты — это отображаемый пересчёт по датированным справочным курсам, а не текущая котировка.' },
  sv: { title: 'Kalkylator för skuld-inkomstkvot', description: 'Jämför din nuvarande skuld-inkomstkvot med ett nytt lån, omvandla belopp mellan EUR, USD, GBP och RUB och testa din egen gräns.', intro: 'En ny månadsbetalning kan verka rimlig ensam men ändra den del av inkomsten som redan går till skulder. Ange dina betalningar och jämför scenariot.', formula: 'Beräkningen är månatliga skuldbetalningar ÷ vald månadsinkomst × 100. Det beräknade scenariot lägger till den nya betalningen.', limit: 'Gränsen hjälper dig att jämföra alternativ men är ingen universell kreditregel. Långivare kan definiera inkomst och skuld på olika sätt.', faq: [{ question: 'Vad är skuld-inkomstkvoten?', answer: 'Det är den andel av den valda månadsinkomsten som går till månatliga skuldbetalningar, uttryckt i procent.' }, { question: 'Ska jag använda brutto- eller nettoinkomst?', answer: 'Välj den grund som passar jämförelsen och använd den i båda scenarierna.' }, { question: 'Förutser kalkylatorn ett godkännande?', answer: 'Nej. Den jämför dina värden och ersätter inte långivarens prövning.' }], howTo: [{ name: 'Välj grund', text: 'Välj valuta och brutto- eller nettoinkomst.' }, { name: 'Lägg till betalningar', text: 'Ange de månatliga skuldbetalningar du redan har.' }, { name: 'Testa det nya lånet', text: 'Lägg till betalning, löptid och gräns.' }, { name: 'Läs förändringen', text: 'Jämför kvoter, kvarvarande inkomst och marginal.' }], seoTitle: 'Jämför nuvarande och beräknad skuldbelastning', seoResultTitle: 'Vad jämförelsen visar', seoResult: 'Den nuvarande kvoten använder befintliga betalningar. Den beräknade kvoten lägger till den nya betalningen och löptiden visar totalsumman.', seoTipTitle: 'Se gränsen som ett scenario', seoTip: 'En gräns hjälper dig jämföra men garanterar inte godkännande. Kontrollera långivarens definitioner och hela budgeten.', seoList: ['Om den nya betalningen överskrider din gräns.', 'Hur mycket inkomst som finns kvar.', 'Hur många procentenheter betalningen lägger till.', 'Den planerade totalsumman under löptiden.'], seoClosing: 'Valutabyte är en visningskonvertering med daterade referenskurser, inte en livekurs.' },
  tr: { title: 'Borç-Gelir Oranı Hesaplayıcı', description: 'Mevcut borç-gelir oranınızı yeni kredi senaryosuyla karşılaştırın, EUR, USD, GBP ve RUB tutarlarını dönüştürün ve seçtiğiniz eşiği test edin.', intro: 'Yeni bir aylık ödeme tek başına makul görünebilir ancak gelirin borca ayrılan kısmını değiştirebilir. Ödemelerinizi girin ve öngörülen senaryoyu karşılaştırın.', formula: 'Hesaplama aylık borç ödemeleri ÷ seçilen aylık gelir × 100 şeklindedir. Öngörülen senaryoya yeni ödeme eklenir.', limit: 'Eşik, seçenekleri karşılaştırmaya yarar; evrensel bir onay kuralı değildir. Kreditörler gelir ve borcu farklı tanımlayabilir.', faq: [{ question: 'Borç-gelir oranı nedir?', answer: 'Seçilen aylık gelirin ne kadarının aylık borç ödemelerine gittiğini yüzde olarak gösterir.' }, { question: 'Brüt mü net gelir mi kullanmalıyım?', answer: 'Karşılaştırmanıza uygun temeli seçin ve iki senaryoda da aynı temeli kullanın.' }, { question: 'Hesaplayıcı onayı öngörür mü?', answer: 'Hayır. Girdiğiniz değerleri karşılaştırır ve kreditör incelemesinin yerini tutmaz.' }], howTo: [{ name: 'Temeli seçin', text: 'Para birimini ve brüt veya net geliri seçin.' }, { name: 'Mevcut ödemeleri ekleyin', text: 'Zaten yaptığınız aylık borç ödemelerini girin.' }, { name: 'Yeni krediyi test edin', text: 'Ödeme, vade ve eşiği ekleyin.' }, { name: 'Değişimi okuyun', text: 'Oranları, kalan geliri ve eşiğe kalan payı karşılaştırın.' }], seoTitle: 'Mevcut ve öngörülen borç yükünü karşılaştırın', seoResultTitle: 'Karşılaştırmanın gösterdiği', seoResult: 'Mevcut oran, var olan ödemeleri kullanır. Öngörülen oran yeni ödemeyi ekler; vade planlanan toplamı gösterir.', seoTipTitle: 'Eşiği karar değil senaryo olarak görün', seoTip: 'Eşik karşılaştırmaya yardımcı olur ama onay garantisi değildir. Kreditör tanımlarını ve bütçenizin tamamını kontrol edin.', seoList: ['Yeni ödemenin seçilen sınırı aşıp aşmadığı.', 'Ödemelerden sonra kalan gelir.', 'Ödemenin eklediği yüzde puan.', 'Girilen vade boyunca planlanan toplam.'], seoClosing: 'Para birimi değişimi, tarihli referans kurlarıyla yapılan gösterim dönüşümüdür; canlı fiyat değildir.' },
  zh: { title: '债务收入比计算器', description: '比较当前债务收入比与新增贷款方案，在 EUR、USD、GBP 和 RUB 之间换算金额，并测试你设定的阈值。', intro: '新增月供单独看似可承受，却可能改变已经用于偿债的收入比例。输入现有付款，查看新增方案的影响。', formula: '计算公式为每月债务还款 ÷ 选定的月收入 × 100。预计方案会加上新增月供。', limit: '阈值用于比较方案，不是通用的审批规则。不同贷款机构对收入、债务和上限的定义可能不同。', faq: [{ question: '什么是债务收入比？', answer: '它表示选定月收入中用于每月偿还债务的比例，并以百分比显示。' }, { question: '应该使用税前还是税后收入？', answer: '选择适合你比较目的的口径，并在两个方案中保持一致。' }, { question: '计算器能预测是否获批吗？', answer: '不能。它只比较你输入的数字，不能替代贷款机构的审核。' }], howTo: [{ name: '选择口径', text: '选择货币以及税前或税后收入。' }, { name: '添加当前还款', text: '输入你目前每月承担的债务还款。' }, { name: '测试新增贷款', text: '填写新增月供、期限和阈值。' }, { name: '查看变化', text: '比较两个比例、剩余收入和距离阈值的空间。' }], seoTitle: '比较当前和预计的债务负担', seoResultTitle: '比较结果能说明什么', seoResult: '当前比例使用已有还款。预计比例会加入新增月供，期限则显示这笔月供的计划总额。', seoTipTitle: '把阈值当作方案，而不是结论', seoTip: '阈值适合比较不同选择，但不能保证获批。请核对贷款机构的定义和完整家庭预算。', seoList: ['新增月供是否超过你设定的上限。', '还款后每月还剩多少收入。', '新增月供增加了多少个百分点。', '整个期限内的计划总额。'], seoClosing: '切换货币是根据带日期的参考汇率进行显示换算，不是实时行情。' },
};

