function makeSchemas(pack: CopyPack, locale: LocaleKey) {
  const faqSchema = { '@context': 'https://schema.org', '@type': 'FAQPage', inLanguage: locale, mainEntity: pack.faq.map((item) => ({ '@type': 'Question', name: item.question, acceptedAnswer: { '@type': 'Answer', text: item.answer } })) };
  const howToSchema = { '@context': 'https://schema.org', '@type': 'HowTo', inLanguage: locale, name: pack.title, description: pack.description, step: pack.howTo.map((step, index) => ({ '@type': 'HowToStep', position: index + 1, name: step.name, text: step.text })) };
  const appSchema = { '@context': 'https://schema.org', '@type': 'SoftwareApplication', inLanguage: locale, name: pack.title, description: pack.description, applicationCategory: 'FinanceApplication', operatingSystem: 'All', offers: { '@type': 'Offer', price: '0', priceCurrency: 'USD' } };
  return [faqSchema, howToSchema, appSchema];
}

export function createLoanToIncomeContent(locale: LocaleKey): ToolLocaleContent<LoanToIncomeRatioUI> {
  const pack = { ...packs[locale], ...copyOverrides[locale] };
  const ui = { ...baseUI, ...uiPatches[locale] };
  const paragraph = (html: string) => `<p>${html}</p>`;
  return {
    slug: localizedSlugs[locale],
    title: pack.title,
    description: pack.description,
    ui,
    faq: pack.faq,
    bibliography,
    howTo: pack.howTo,
    schemas: makeSchemas(pack, locale),
    seo: [
      { type: 'title', text: pack.seoTitle, level: 2 },
      { type: 'paragraph', html: paragraph(pack.intro) },
      { type: 'title', text: formulaTitles[locale], level: 3 },
      { type: 'paragraph', html: paragraph(pack.formula) },
      { type: 'tip', title: pack.seoTipTitle, html: `<p>${pack.seoTip}</p>` },
      { type: 'title', text: pack.seoResultTitle, level: 3 },
      { type: 'paragraph', html: paragraph(pack.seoResult) },
      { type: 'list', items: pack.seoList },
      { type: 'paragraph', html: paragraph(pack.seoClosing) },
      { type: 'paragraph', html: paragraph(pack.limit) },
    ],
  };
}
